import { useEffect, useState } from "react";
import axios from "axios";

export default function WeatherOujdaHistory() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getWeather = async () => {
      try {
        const res = await axios.get(
          "https://api.open-meteo.com/v1/forecast?latitude=34.68&longitude=-1.91&past_days=7&daily=temperature_2m_max,temperature_2m_min&timezone=Africa/Casablanca"
        );
        setData(res.data);
      } catch (err) {
        console.log('Error:', err);
      } finally {
        setLoading(false);
      }
    };

    getWeather();
  }, []);

  if (loading) return <p>Loading...</p>;

  return (
    <div style={{ color: "white" }}>
      <h2>Weather History — Oujda (Last 7 Days)</h2>

      {data?.daily?.time?.map((day, i) => (
        <p key={day}>
          📅 {day} — Max: {data.daily.temperature_2m_max[i]}°C | Min:{" "}
          {data.daily.temperature_2m_min[i]}°C
        </p>
      ))}
    </div>
  );
}
